// See the original script for more information:
// https://github.com/impresso/impresso-frontend/blob/feature/radio-content-item/src/scripts/generateTypes.ts
import * as fs from 'node:fs';
import { compileFromFile } from 'json-schema-to-typescript';

const banner: string = `
/* eslint-disable */
/**
 * This file was automatically generated by json-schema-to-typescript.
 * DO NOT MODIFY IT BY HAND. Instead, modify the source src/_common/metadata.py file,
 * and run 'npm run copy:metadata' to regenerate this file.
 */
`

// const inputFile: string = '/tmp/efs/metadata.json';
// const outputFile: string = './types/metadata.d.ts';
// const inputFile: string = './scripts/schemas/RefDatapoint.json';
// const outputFile: string = './types/RefDatapoint.d.ts';
// const inputPath: string = './scripts/schemas';
// const outputPath: string = './types/metadata';

const inputPath: string = `./scripts/schemas`;
const outputPath: string = './types';

const directories = fs
    .readdirSync(inputPath, {
        recursive: true
    })
    .filter((item: string) => {
        const s = fs.statSync(`${inputPath}/${item}`);
        return s.isDirectory();
    }) as string[];

async function compileDirectory(
    inputPath: string,
    dir: string,
    outputBasePath: string
): Promise<void> {
    const dirPath: string = `${inputPath}/${dir}`;
    const files: string[] = fs.readdirSync(dirPath).filter((item: string) => {
        const path = `${dirPath}/${item}`;
        const isDir = fs.statSync(path).isDirectory();
        return !isDir;
    })
    // eslint-disable-next-line no-console
    console.log(`Found ${files.length} files in the "${dir}" directory.`);
    const tsContents: string[] = await Promise.all(
        files.map((fileName: string) => {
            const inputFile = `${dirPath}/${fileName}`;
            console.info(`\tTransforming "${inputFile}".`);
            return compileFromFile(inputFile, {
                bannerComment: ''
            })
        })
    )
    const content: string = [banner, ...tsContents].join('\n\n');
    const outputFile: string = `${outputBasePath}/${dir}.d.ts`;
    fs.writeFileSync(outputFile, content);
}

async function compileAll(
    inputPath: string,
    outputPath: string,
    directories: string[]
): Promise<void> {
    console.log("Step 3. Transforming JSON schemas to TypeScript interfaces.");
    for (const dir of directories) {
        // eslint-disable-next-line no-console
        await compileDirectory(inputPath, dir, outputPath);
    }
}

compileAll(inputPath, outputPath, directories)
    .then(() => {
        // eslint-disable-next-line no-console
        console.info("Finished.");
    })
    .catch((e: Error) => console.error(e));
